const readStore=<T,>(key:string,fallback:T):T=>{try{const value=localStorage.getItem(key);return value?JSON.parse(value) as T:fallback}catch{return fallback}};
function useNotice(){const {toast}=useApp();return toast;}
function Verified(){return <span className="verified" title="Student identity verified"><Check size={11}/> Verified student</span>}
function Avatar({creator,size=''}:{creator:Creator;size?:string}){return <span className={`avatar ${size}`}>{creator.initials}</span>}
function Button({children,onClick,variant='',className='',type='button',testid,style}:{children:ReactNode;onClick?:()=>void;variant?:string;className?:string;type?:'button'|'submit';testid?:string;style?:import('react').CSSProperties}){return <button type={type} onClick={onClick} data-testid={testid} style={style} className={`btn ${variant} ${className}`}>{children}</button>}
function PageHeader({eyebrow,title,description,action}:{eyebrow?:string;title:string;description?:string;action?:ReactNode}){return <div className="section-head"><div>{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h1 className="page-title">{title}</h1>{description&&<p className="subhead">{description}</p>}</div>{action}</div>}
function ArtCard({art,rank}:{art:Art;rank?:number}){const {toggleSave,toggleLike,wishlist,liked}=useApp();const creator=creatorOf(art.creatorId);return <article className="art-card" data-testid={`card-artwork-${art.id}`}><div className="art-image-wrap"><Link href={`/artwork/${art.id}`} style={{display:'block',height:'100%'}}><img className="art-image" src={art.image} alt={art.title}/><div className="art-gradient"/>{(rank||art.rank)&&<span className="rank">#{rank||art.rank} · TRENDING</span>}</Link><div className="art-action"><button className={`round-action ${liked.includes(art.id)?'selected':''}`} aria-label={`Like ${art.title}`} data-testid={`button-like-${art.id}`} onClick={()=>toggleLike(art.id)}><Heart size={14} fill={liked.includes(art.id)?'currentColor':'none'}/></button><button className={`round-action ${wishlist.includes(art.id)?'selected':''}`} aria-label={`Save ${art.title}`} data-testid={`button-save-${art.id}`} onClick={()=>toggleSave(art.id)}><Bookmark size={14} fill={wishlist.includes(art.id)?'currentColor':'none'}/></button></div></div><div className="art-meta"><div className="art-line"><Link href={`/artwork/${art.id}`} className="art-title">{art.title}</Link><span className="price">₹{art.price.toLocaleString('en-IN')}</span></div><Link href={`/creator/${creator.id}`} className="creator-line"><Avatar creator={creator}/><span>{creator.name}</span><Verified/></Link><div className="stats-inline"><span><Heart size={11}/>{art.likes.toLocaleString()}</span><span><Bookmark size={10}/>{art.saves}</span><span><Eye size={11}/>{(art.views/1000).toFixed(1)}k</span></div></div></article>}
function ArtGrid({items}:{items:Art[]}){return items.length?<div className="art-grid">{items.map(a=><div key={a.id}><ArtCard art={a}/><Link href={`/artwork/${a.id}`} className="btn small view-artwork" data-testid={`link-view-artwork-${a.id}`}>View artwork <ArrowUpRight size={12}/></Link></div>)}</div>:<div className="empty"><Search size={25}/><h3>No artwork found</h3><p>Try adjusting your search or filters to discover something new.</p></div>}
function CreatorCard({creator}:{creator:Creator}){const {following,toggleFollow}=useApp();const followingNow=following.includes(creator.id);return <article className="creator-card" data-testid={`card-creator-${creator.id}`}><div className="creator-top"><Avatar creator={creator} size="large"/><div style={{flex:1}}><h3>{creator.name}</h3><p>{creator.college}</p></div><Verified/></div><p className="micro" style={{lineHeight:1.65,margin:'16px 0'}}>{creator.bio}</p><div>{creator.skills.slice(0,3).map(s=><span className="chip" key={s}>{s}</span>)}</div><div className="creator-line" style={{marginTop:16}}><Users size={12}/>{creator.followers.toLocaleString()} followers <span>·</span> {creator.works} works</div><div style={{display:'flex',gap:8,marginTop:15}}><Link href={`/creator/${creator.id}`} className="btn small" style={{flex:1}}>View profile <ArrowUpRight size={13}/></Link><Button variant={followingNow?'':'primary'} className="small" onClick={()=>toggleFollow(creator.id)}>{followingNow?'Following':'Follow'}</Button></div></article>}
function SearchIconLink(){return <Link href="/explore" className="icon-link" aria-label="Search artwork" data-testid="link-search"><Search size={17}/></Link>}
const navMain=[['Home','/home'],['Explore','/explore'],['Trending','/trending'],['Creators','/creators'],['Commissions','/commissions'],['Collaborate','/collaborate']];
